import { computed, inject, Injectable, NgZone, signal } from '@angular/core';
import { ApplicationConfig, MODULE_NAME } from 'espd-common/config';
import { MessageService } from 'espd-common/i18n';
import { ModalService, WorkflowRef } from 'espd-common/modal';
import { SettingService, SettingType } from 'espd-common/setting';
import { WindowService } from 'espd-common/window';
import { BsModalService } from 'ngx-bootstrap/modal';
import { SessionCountdownComponent } from './modal/session-countdown.component';

export enum SessionState { live, expiring, expired }
export enum ModalResult { reloadWindow, logOut, refreshSession }

@Injectable()
export class SessionService {
	private readonly lastActionKey = 'common.LastActionTime';

	private sessionTimerId?: number;
	private sessionDurationSeconds = signal(30 * 60);
	private configured = false;
	private dialogRef?: WorkflowRef<ModalResult | undefined>;

	private logOutAction?: () => any;
	private refreshAction?: () => any;

	private appConfig = inject(ApplicationConfig);
	private bsModalService = inject(BsModalService);
	private messageService = inject(MessageService);
	private modalService = inject(ModalService);
	private windowService = inject(WindowService);
	private settingService = inject(SettingService);
	private zone = inject(NgZone);

	public readonly secondsToExpiration = signal(this.sessionDurationSeconds());
	public readonly sessionState = computed(() => this.getSessionState());
	public readonly canLogOut = signal(false);
	public readonly sessionDurationMinutes = computed(() => this.sessionDurationSeconds() / 60)

	private get isEnabled(): boolean {
		return this.configured && this.sessionDurationSeconds() > 0;
	}

	constructor() {
		this.settingService.waitFor(MODULE_NAME).subscribe(() => {
			const durationSetting = this.settingService.get(SettingType.SESSION_DURATION_SECONDS);
			if (typeof durationSetting === 'number') {
				this.sessionDurationSeconds.set(durationSetting);
			}
		});
	}

	public configure(logOutAction?: () => any, refreshAction?: () => any): void {
		this.configured = true;
		this.logOutAction = logOutAction;
		this.refreshAction = refreshAction;
		this.canLogOut.set(!!logOutAction);
		this.resetSessionExpirationTimer();
	}

	public logOut(): void {
		localStorage.setItem(this.lastActionKey, '0');
		if (this.logOutAction) {
			this.closeModal();
			this.logOutAction();
		} else {
			this.lostSession();
		}
	}

	public refreshSession(): void {
		if (this.refreshAction && this.sessionState() !== SessionState.expired) {
			this.refreshAction();
			this.resetSessionExpirationTimer();
		} else {
			this.windowService.nativeWindow.location.reload();
		}
	}

	public resetSessionExpirationTimer(): void {
		if (this.isEnabled) {
			this.clearIntervalTimer();
			if (this.sessionDurationSeconds() > 0) {
				localStorage.setItem(this.lastActionKey, new Date().getTime().toFixed(0));
				this.zone.runOutsideAngular(() => {
					this.sessionTimerId = window.setInterval(
						() => this.checkSessionTimeout(),
						1000
					);
				});
			}
		}
	}

	public lostSession(): void {
		this.displayModal('expired');
	}

	private getSessionState(): SessionState {
		if (this.secondsToExpiration() <= 0) {
			return SessionState.expired;
		} else if (this.secondsToExpiration() <= 60) {
			return SessionState.expiring;
		} else {
			return SessionState.live;
		}
	}

	public getSecondsToExpiration(): number {
		const datetime = new Date().getTime();
		const lastActionTime = parseInt(localStorage.getItem(this.lastActionKey) ?? '0', 10);
		const millisSinceLastAction = datetime - lastActionTime;
		return Math.max(0, Math.floor((this.sessionDurationSeconds() * 1000 - millisSinceLastAction) / 1000));
	}

	private checkSessionTimeout() {
		this.secondsToExpiration.set(this.getSecondsToExpiration());
		const state = this.sessionState();
		if (state === SessionState.expired) {
			this.clearIntervalTimer();
			this.logOut();
		} else if (state === SessionState.expiring) {
			this.aboutToLoseSession();
		}
	}

	private aboutToLoseSession() {
		this.displayModal('countdown');
	}

	private displayModal(state: 'countdown' | 'expired') {
		if (this.dialogRef) {
			this.dialogRef.modalRef.content?.setState(state);
		} else {
			this.openNewSessionModal(state);
		}
	}

	private closeModal() {
		this.dialogRef?.modalRef.hide();
	}

	private openNewSessionModal(initialState: 'countdown' | 'expired') {
		this.bsModalService.hide();

		setTimeout(() => {
			const appName = this.settingService.get(this.appConfig.applicationNameSetting);
			const expiredBody = this.messageService.get('common.lostSessionDialog.body', appName);

			this.dialogRef = this.modalService.showWorkflowRef<ModalResult>(
				{ key: 'common.lostSessionDialog.header' },
				{
					states: {
						countdown: {
							title: { key: 'common.sessionDialog.header' },
							component: { type: SessionCountdownComponent },
							buttons: [
								{ content: this.messageService.get('common.sessionDialog.button.refresh'), value: ModalResult.refreshSession },
								...(this.canLogOut() ? [{ content: this.messageService.get('common.sessionDialog.button.logOut'), value: ModalResult.logOut, secondary: true }] : []),
							]
						},
						expired: {
							body: expiredBody,
							buttons: [{ content: this.messageService.get('common.lostSessionDialog.button'), value: ModalResult.reloadWindow }]
						}
					},
					initialState
				}
			);

			this.dialogRef.result.subscribe(result => {
				this.clearIntervalTimer();
				switch (result) {
					case ModalResult.logOut:
						this.logOut();
						break;
					case ModalResult.refreshSession:
						this.refreshSession();
						break;
					case ModalResult.reloadWindow:
						this.windowService.nativeWindow.location.reload();
				}
				this.dialogRef = undefined;
			});
		}, 475); // delay so we don't accidentally get the onHide event from the hide() call, which is delayed 450ms
	}

	private clearIntervalTimer() {
		if (this.sessionTimerId) {
			clearInterval(this.sessionTimerId);
			this.sessionTimerId = undefined;
		}
	}
}