import { HttpErrorResponse, HttpEvent, HttpHandler, HttpInterceptor, HttpRequest } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { HttpStatus } from 'espd-common/data';
import { noop, Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { SessionService } from './session.service';

@Injectable()
export class SessionInterceptor implements HttpInterceptor {

	private sessionService = inject(SessionService);

	public intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
		if (!req.url.startsWith('https://') && !req.url.startsWith('http://')) {
			// only calls to cross-origin endpoints should have the http(s) prefix
			this.sessionService.resetSessionExpirationTimer();
		}

		return next.handle(req).pipe(tap(
			noop,
			(err: unknown) => {
				if (err instanceof HttpErrorResponse && err.status === HttpStatus.unauthorized) { // no session
					this.sessionService.lostSession();
				}
			}
		));
	}
}